input.command:
# Find NHA terms without VeNom content
grep "^id: MONDO:101" src/ontology/mondo-edit.obo | while read line; do
  id=$(echo $line | sed 's/^id: //');
  grep -A1 "^$line" src/ontology/mondo-edit.obo | grep -q "non-human animal" && {
    grep -A50 "^id: $id\$" src/ontology/mondo-edit.obo | grep -q "VeNom:" || echo "$id";
  }
done | head -10 | while read id; do
  echo "=== $id ==="
  grep -A5 "^id: $id\$" src/ontology/mondo-edit.obo | head -6
done
